def find_sofa(d, n, m, sofas, cnt_l, cnt_r, cnt_t, cnt_b):
    # Create a matrix to store the sofas
    sofa_matrix = [[0 for _ in range(m)] for _ in range(n)]

    # Store the coordinates of the sofas in the matrix
    for i in range(d):
        x, y = sofas[i][0], sofas[i][1]
        sofa_matrix[x-1][y-1] = i+1

    # Check if there is any sofa that satisfies all the conditions
    count = 0
    for i in range(n):
        for j in range(m):
            if sofa_matrix[i][j] != 0:
                l = sofa_matrix[i][j]-1
                r = sofa_matrix[i][j]
                if sofa_matrix[i][j-1] != 0:
                    r += 1
                if sofa_matrix[i][j+1] != 0:
                    r += 1
                if sofa_matrix[i-1][j] != 0:
                    l += 1
                if sofa_matrix[i+1][j] != 0:
                    l += 1
                if sofa_matrix[i][j-1] != sofa_matrix[i][j+1]:
                    if sofa_matrix[i][j-1] != sofa_matrix[i][j+1]:
                        if sofa_matrix[i][j-1] < sofa_matrix[i][j+1]:
                            count += 1

    # Check if the count is equal to the number of sofas
    if count == d:
        return sofa_matrix[n-1][m-1]
    else:
        return -1

