    s = input()
    m = len(s)
    pi = prefix_function(s)
    dp = [[[0] * (m + 1) for _ in range(m)] for _ in range(n + 1)]
    dp[0][0][0] = 1
    for i in range(n):
        for j in range(m):
            for k in range(m + 1):
                for l in range(2):
                    if dp[i][j][k]:
                        for c in range(2):
                            nj = j
                            while nj > 0 and chr(ord('0') + c) != s[nj]:
