def find_sequence(n, k):
    if k > n or k * (k + 1) // 2 > n:
        return -1

    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)

