def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def count_ways(n, k, cards):
    ways = 0
    prefix = [0] * (n + 1)
    suffix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i - 1] + gcd(cards[i - 1], k)
    for i in range(n, 0, -1):
        suffix[i] = suffix[i + 1] + gcd(cards[i - 1], k)
    for i in range(n + 1):
        ways += prefix[i] * suffix[i]
    return ways

