def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def lcm(a, b):
    return a * b // gcd(a, b)

def solve(t, w, b):
    lcm_val = lcm(w, b)
    total_possible_steps = t // lcm_val
    willman_steps = t // w
    bolt_steps = t // b
    common_steps = t // lcm_val

