        i += 2
    return True

def represent_as_primes(n):
    primes = []

    # Check if n is prime
    if is_prime(n):
        primes.append(n)
        return 1, primes

    # Check for the first prime <= n
    i = 2
    while True:
        if is_prime(i):
            if i == n:
                primes.append(i)
                return 1, primes
            elif i + 2 <= n and is_prime(i + 2):
                if i + 2 == n:
                    primes.append(i)
                    primes.append(i + 2)
                    return 2, primes
                elif i + 2 + 6 <= n and is_prime(i + 2 + 6):
                    primes.append(i)
                    primes.append(i + 2)
                    primes.append(i + 2 + 6)
                    return 3, primes
            i += 1

