from collections import defaultdict

def dfs(graph, start, visited, recursion_stack):
    visited[start] = True
    recursion_stack[start] = True

    for neighbor in graph[start]:
        if not visited[neighbor]:
            if dfs(graph, neighbor, visited, recursion_stack):
                return True
        elif recursion_stack[neighbor]:
            return True

    recursion_stack[start] = False
    return False

def is_acyclic(graph, n, m):
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i] and dfs(graph, i, visited, recursion_stack):
            return False

    return True

def solve():
    n, m = map(int, input().split())
    graph = defaultdict(list)

    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)

    if is_acyclic(graph, n, m):
        print("YES")
    else:
        edges_to_remove = []

        for i in range(1, n + 1):
            visited = [False] * (n + 1)
            recursion_stack = [False] * (n + 1)

            if dfs(graph, i, visited, recursion_stack):
                edges_to_remove.append(i)

        if len(edges_to_remove) > 1:
            print("NO")
        else:
            print("YES")

solve()

