def can_be_false(expression):
    stack = []
    for arg in expression:
        if arg == '0':
            stack.append(arg)
        elif arg == '1':
            if stack and stack[-1] == '0':
                stack.pop()
        else:
            raise ValueError("Invalid character in expression")
    return not stack

def find_brackets(expression):
    n = len(expression)
    if can_be_false(expression):
        return "YES\n" + expression

    for i in range(n):
        if expression[i] == '1':
            for j in range(i + 1, n):
                if expression[j] == '0':
                    new_expression = expression[:i] + '(' + expression[i:j+1] + ')' + expression[j+1:]
                    if can_be_false(new_expression):
