from math import gcd
from collections import defaultdict
def region_count(n, circles):
    def distance(p1, p2):
        return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

    def intersection(circle1, circle2):
        d = distance(circle1[:2], circle2[:2])
        if d > circle1[2] + circle2[2]:
            return None
        if d < abs(circle1[2] - circle2[2]):
            return None
        t = (d ** 2 - circle1[2] ** 2 + circle2[2] ** 2) / (2 * d)
        if t < 0 or t > 1:
            return None
        x = circle1[0] + t * (circle2[0] - circle1[0])
        y = circle1[1] + t * (circle2[1] - circle1[1])
        return x, y

    def gcdExtended(a, b, x, y):
        if a == 0:
            x[0], y[0] = 1, 0
            return b
        x1, y1 = gcdExtended(b % a, a, x, y)
        x[0], y[0] = y1, x1 - (b // a) * y1
        return x1

    def find_circle_region(circle, regions):
        region = set()
        stack = [(circle, set())]
        while stack:
            c, visited = stack.pop()
            if c in region:
                continue
            region.add(c)
            for other in circles:
                if other not in visited and other != c and intersection(c, other) is not None:
                    stack.append((other, visited | {c}))
        return region

    def merge_regions(regions):
        graph = defaultdict(set)
        for r1 in regions:
            for r2 in regions:
                if r1 != r2:
                    for p1 in r1:
                        for p2 in r2:
                            if distance(p1, p2) == 0:
                                graph[r1].add(r2)
                                graph[r2].add(r1)
                                break
        components = []
        for region in regions:
            if region not in components:
                component = {region}
                queue = [region]
                while queue:
                    r = queue.pop(0)
                    for nei in graph[r]:
                        if nei not in component:
                            component.add(nei)
                            queue.append(nei)
                components.append(component)
        return sum(len(c) for c in components)

    def compute_regions(circles):
        regions = set()
        for circle in circles:
            region = find_circle_region(circle, regions)
            regions -= region
            regions.add(region)
        return len(regions)

    n_circles = int(input())
    circles = []
    for _ in range(n_circles):
        x, y, r = map(int, input().split())
        circles.append((x, y, r))

    # Handle infinite region
    gcd_val = gcd(*map(lambda c: c[2], circles))
    circles = [(x, y, r // gcd_val) for x, y, r in circles]

    return compute_regions(circles)

