    blacklist_set = set()
    whitelist_set = set()

    # Convert subnets to ranges of addresses
    def subnet_to_range(subnet):
        if '/' in subnet:
            ip, bits = subnet.split('/')
            mask = (1 << (32 - int(bits))) - 1
            return (int(ip.replace('.', '')) & ~mask, int(ip.replace('.', '')) | mask)
        else:
            return (int(subnet.replace('.', '')), int(subnet.replace('.', '')) + 1)

