def min_moves(grid, goals):
    n, m = len(grid), len(grid[0])
    moves = 0
    queue = [(grid.copy(), [])]
    while queue:
        curr_grid, path = queue.pop(0)
        if is_goal(curr_grid, goals):
            return moves + len(path)
        for i in range(n):
            add_to_row(curr_grid, i)
            if is_valid(curr_grid, goals):
                queue.append((curr_grid, path + [f"row {i}"]))
                moves += 1
        for j in range(m):
            add_to_column(curr_grid, j)
            if is_valid(curr_grid, goals):
                queue.append((curr_grid, path + [f"col {j}"]))
                moves += 1
        add_to_grid(curr_grid, 0)
    return -1

def add_to_row(grid, row):
    for col in range(len(grid[0])):
        grid[row][col] += 1

def add_to_column(grid, col):
    for i in range(len(grid)):
        grid[i][col] += 1

def add_to_grid(grid, num):
    grid[num][num] += 1

def is_valid(grid, goals):
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell != goals[i][j]:
                return False
    return True

def is_goal(grid, goals):
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell != goals[i][j]:
                return False
    return True

