import heapq

def solve():
    n, m = map(int, input().split())
    volcanoes = set()
    for _ in range(m):
        x, y = map(int, input().split())
        volcanoes.add((x, y))
    queue = [(0, 1, 1)]
    visited = set()
    while queue:
        time, x, y = heapq.heappop(queue)
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if (x, y) == (n, n):
            return time
        for dx, dy in [(1, 0), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= n and (nx, ny) not in volcanoes:
                heapq.heappush(queue, (time + 1, nx, ny))
    return -1

