from collections import defaultdict

def find_shortest_cycle(n, a):
    # Create a graph where nodes i and j are connected if a[i] & a[j] != 0
    graph = defaultdict(list)
    for i in range(n):
        for j in range(i+1, n):
            if a[i] & a[j] != 0:
                graph[i].append(j)
                graph[j].append(i)

    # Perform a depth-first search to find the shortest cycle
    visited = [False] * n
    parent = [-1] * n
    cycle_length = float('inf')

    def dfs(node, depth):
        nonlocal cycle_length
        visited[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                dfs(neighbor, depth + 1)
            elif neighbor != parent[node]:
                cycle_length = min(cycle_length, depth + 1)

    for i in range(n):
        if not visited[i]:
            dfs(i, 0)

    return cycle_length if cycle_length != float('inf') else -1

