def xor(a, b):
    return a ^ b

def xor_set(S):
    if len(S) == 1:
        return S
    else:
        return [xor(S[0], S[1])] + xor_set(S[2:])

def is_perfect(S):
    for i in range(len(S)):
        for j in range(i + 1, len(S)):
            if xor(S[i], S[j]) not in S:
                return False
    return True

def solve(k):
    S = [0]
    while S[-1] < k:
