    # Read input
    H, W = map(int, input().split())
    grid = [list(input()) for _ in range(H)]

    # Find the positions of S and T
    sx, sy = None, None
    tx, ty = None, None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                sx, sy = i, j
            elif grid[i][j] == 'T':
                tx, ty = i, j

    # Check if it is possible to reach T from S
    if not can_reach(grid, sx, sy, tx, ty):
        print(-1)
        return

    # Find the minimum number of leaves to remove
    min_leaves = float('inf')
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'o':
                # Remove the leaf at (i, j) and check if it is still possible to reach T from S
                grid[i][j] = '.'
                if not can_reach(grid, sx, sy, tx, ty):
                    min_leaves = min(min_leaves, 1)
                else:
                    # Restore the leaf at (i, j)
                    grid[i][j] = 'o'

    # Print the minimum number of leaves to remove
    print(min_leaves)

def can_reach(grid, sx, sy, tx, ty):
    # Create a queue to store the squares to visit
    queue = [(sx, sy)]

    # Create a set to store the squares that have been visited
    visited = set()

    # While there are still squares to visit
    while queue:
        # Get the next square to visit
        x, y = queue.pop(0)

        # If the current square is T, then we have reached the destination
        if x == tx and y == ty:
            return True

        # If the current square has not been visited
        if (x, y) not in visited:
            # Mark the current square as visited
            visited.add((x, y))

            # Add the adjacent squares to the queue
            if x > 0 and grid[x-1][y] != '.':
                queue.append((x-1, y))
            if x < len(grid)-1 and grid[x+1][y] != '.':
                queue.append((x+1, y))
            if y > 0 and grid[x][y-1] != '.':
                queue.append((x, y-1))
            if y < len(grid[0])-1 and grid[x][y+1] != '.':
                queue.append((x, y+1))

    # If we have not reached the destination, then it is not possible to reach T from S
    return False

