from collections import deque

def bfs(grid, start, n, m):
    queue = deque([(start[0], start[1])])
    visited = set()
    visited.add((start[0], start[1]))
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return visited

def solve(n, m, k, grid):
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))

    if k >= len(empty_cells):
        return ['X' * m for _ in range(n)]

    for i in range(len(empty_cells)):
        new_grid = [list(row) for row in grid]
        for j in range(len(empty_cells)):
            if j < i:
                new_grid[empty_cells[j][0]][empty_cells[j][1]] = 'X'

        start = empty_cells[i]
        visited = bfs(new_grid, start, n, m)
        if len(visited) == len(empty_cells) - k:
            for j in range(i):
                grid[empty_cells[j][0]][empty_cells[j][1]] = 'X'
            return [''.join(row) for row in grid]

    return []

n, m, k = map(int, input().split())
grid = [input() for _ in range(n)]
result = solve(n, m, k, grid)
if result:
    print('\n'.join(result))
else:
    print("No solution found")

