def max_prefix_count(n, k, s, t):
    count_a = 0
    count_b = 0
    max_count = 0
    for i in range(n):
        if s[i] == 'a':
            count_a += 1
        elif s[i] == 'b' and t[i] == 'a':
            count_a += 1
        elif s[i] == 'b':
            count_b += 1

        if s[i] == t[i]:
            max_count += min(count_a, count_b)
        else:
            max_count += count_a

        if s[i] == 'a':
            count_a = max(count_a, count_b)
        else:
            count_b = max(count_b, count_a)

    return min(k, max_count + count_a)

