    # Check if the points form a cube
    if not check_cube(points):
        return False

    # Check if the points have integer coordinates
    for point in points:
        if any(x % 1!= 0 for x in point):
            return False

    # Check if the points are distinct
    point_set = set()
    for point in points:
        if point in point_set:
            return False
        point_set.add(point)

    return True

