from collections import deque

def rearrange_schedule(s, t):
    n, m = len(s), len(t)
    count = [0] * (n - m + 1)

    # Count the number of occurrences of t in s
    for i in range(n - m + 1):
        if s[i:i+m] == t:
            count[i] = 1

    # Rearrange the schedule to maximize the number of occurrences of t
    result = [0] * n
    queue = deque()

    for i in range(n):
        if s[i] == '1':
            while queue and count[queue[0]] == 0:
                result[queue.popleft()] = '1'
            queue.append(i)
        else:
            result[i] = '0'

    while queue:
        result[queue.popleft()] = '1'

    return ''.join(result)

