def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def transform(n, m):
    if n == m:
        return 0
    if n > m:
        n, m = m, n

    if gcd(n, m) > 1:
        return -1

    if m % 2 == 0 and n % 2 == 0:
        steps = transform(n // 2, m // 2)
        return steps + 1 if steps != -1 else steps

    if m % 2 == 0:
        return -1

    if n % 3 == 0 and m % 3 == 0:
        steps = transform(n // 3, m // 3)
        return steps + 1 if steps != -1 else steps

    if n % 3 == 0:
        return -1

    steps = transform(n, m) + 1 if n < m else -1
    return steps

