def max_teams(n, k, a):
    # Sort the array in ascending order
    a.sort()
    # Initialize the result variable
    result = 0
    # Initialize the first team
    first_team = set()
    # Iterate through the array
    for i in range(n):
        # If the difference between the current skill and the skill of the last student in the first team is within 5
        if abs(a[i] - a[first_team[-1]]) <= 5:
            # Add the current student to the first team
            first_team.add(i)
        else:
            # If the first team is not empty and the difference between the skill of the last student in the first team and the skill of the current student is within 5
            if first_team and abs(a[first_team[-1]] - a[i]) <= 5:
                # Add the current student to the first team
                first_team.add(i)
            # Initialize the first team
            first_team = {i}
    # Add the remaining students to the teams
    for i in range(n):
        if i not in first_team:
            # Find the team with the largest skill difference
            largest_diff = -1
            largest_team = -1
            for j in first_team:
                diff = abs(a[i] - a[j])
                if diff > largest_diff:
                    largest_diff = diff
                    largest_team = j
            # Add the current student to the team with the largest skill difference
            if largest_diff <= 5:
                first_team.add(i)
            else:
                # If the team with the largest skill difference is not empty and the difference between the skill of the last student in the first team and the skill of the current student is within 5
                if first_team and abs(a[first_team[-1]] - a[i]) <= 5:
                    first_team.add(i)
    # Return the total number of students in the balanced teams
    return len(first_team)

