def minimum_hugs(s):
    # Initialize a dictionary to keep track of the number of hugs needed for each character in the string
    hugs = {c: 0 for c in s}

    # Loop through the string and keep track of the number of hugs needed for each character
    for i in range(len(s)):
        # If the current character is not a palindrome, increase the hugs count for that character
        if s[i] not in hugs:
            hugs[s[i]] = 1
        # If the current character is a palindrome, decrease the hugs count for that character
        elif s[i] in hugs:
            hugs[s[i]] -= 1

    # Return the minimum number of hugs needed to make the string palindromic
    return min(hugs.values())

